public sealed class SideWellObservationService
{
    public const string ContractVersion="r3-sidewell-safe-observation-candidate-1",SafetyId="R3-O02:entry-safety",VisitId="R3-O02:actual-visit",MeaningId="R3-O02:note-meaning",ResultId="R3-O02:comparison-note",Task="R3-O02-W-CONTEXT",Material="R3-O02-R-OBSERVE",MainMaterial="R3-Q301-R-ENVIRONMENT",Completion="R3-O02:comparison-note-registered";
    private readonly IAdventureRepository _repository;private readonly RuntimeCatalog _catalog;private readonly ChapterThreeService _chapter;
    private readonly Dictionary<Guid,CommitPlanCommand> _previews=[];
    public ChapterMaterial Observation {get;}public ChapterMaterial MainObservation {get;}public ChapterWritingTask WritingTask {get;}
    public SideWellObservationService(IAdventureRepository repository,RuntimeCatalog catalog,ChapterThreePackage package)
    {ChapterThreePackage.Validate(package);_repository=repository;_catalog=catalog;_chapter=new(repository,catalog,package);Observation=package.Materials.Single(x=>x.Id==Material);MainObservation=package.Materials.Single(x=>x.Id==MainMaterial);WritingTask=package.WritingTasks.Single(x=>x.Id==Task);Require(Observation.Version=="r3-author-candidate-1"&&Observation.SourceRoot=="r3-sidewell-optional-observation"&&Observation.AccessClass=="public"&&WritingTask.Spot=="R3-O02.side_route"&&MainObservation.SourceRoot=="r3-current-environment-original","侧井原件合同未绑定，不能猜造采样任务。");Require(_catalog.ReleaseId==repository.Session.ReleaseId,"侧井与当前发布版本不一致。");}
    private static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
    private static T? Read<T>(BranchSnapshot s,string id) where T:class=>BranchOperations.Read<T>(s,id);
    private static ActorState Actor(BranchSnapshot s)=>Read<ActorState>(s,"actor")??throw new InvalidOperationException("当前角色没有真实现场。");
    private static void Safe(BranchSnapshot s)
    {BranchOperations.Safe(s);Require(!s.Entities.Where(e=>e.Kind=="event").Select(e=>StrictJson.Deserialize<EventSession>(e.Json)).Any(e=>e.State==EventLifecycle.Running),"请先交接前景事件。");Require(!s.Entities.Where(e=>e.Kind=="transport_segment").Select(e=>StrictJson.Deserialize<TransportSegment>(e.Json)).Any(t=>t.CargoInTransit&&!t.Completed),"可选侧井不能带未交接救援或货物离开规定运输段。");Require(!BranchOperations.Receipt(s,"Q-604")&&BranchOperations.Entity(s,"final:preparation") is null,"最终封存后外区观察暂停。");}
    private static StoredReceipt Station(BranchSnapshot s,string semantic,string action,string stand)
    {var r=s.Receipts.SingleOrDefault(x=>x.SemanticKey==semantic&&x.ActionType=="chapter_three_station_action")??throw new InvalidOperationException("独立返回梯道、防护或本地委托没有实际来源。");using var j=JsonDocument.Parse(r.ResultJson);Require(j.RootElement.GetProperty("action").GetString()==action&&j.RootElement.GetProperty("actual_stand").GetString()==stand,"本地安全工作来源站位或类型不符。");return r;}
    private (StoredReceipt Ladder,StoredReceipt Rail,StoredReceipt Basic) MainSafety(BranchSnapshot s)
    {
        Safe(s);var st=Read<ChapterThreeState>(s,"chapter3");Require(st is not null&&st.ContentVersion==Observation.Version&&st.Landing&&st.Commission&&st.EntryInstructions&&st.BasicGear&&st.LadderSafe,"矿区真实登记、地方安全说明、防护和独立梯道须先成立。");Require(s.Receipts.Any(r=>r.ActionType=="chapter_three_region_initialized"),"没有真实矿区初始化来源。");Station(s,"R3:local_work","request_local_work","R3-S02.pera");var basic=Station(s,"R3:basic_delivery","receive_basic_supplies","R3-S02.shelter");var ladder=Station(s,"R3:independent_ladder","inspect_ladder","R3-S04.ladder_check");Require(s.Items.SingleOrDefault(i=>i.Id=="R3-local:safety_kit:1") is{DefinitionId:"R3-LOCAL-SAFETY-KIT",OwnerKind:"installed",OwnerId:"R3:patrol_safety_kit"},"本次实际防护套件被挪用。");var rail=s.Receipts.SingleOrDefault(r=>r.SemanticKey=="R3:ENC-R3-01:result"&&r.ActionType=="chapter_three_encounter_result")??throw new InvalidOperationException("轨道当前危险尚未实际处置。");var result=Read<MiningEncounterResult>(s,"R3:result:ENC-R3-01");Require(result is{Completed:true,Encounter:"ENC-R3-01"}&&StrictJson.Serialize(result)==rail.ResultJson,"轨道处置当前实例与原结果不符。");return(ladder,rail,basic);
    }
    public static bool OwnPort(string id)=>id is "R3-S05.to.R3-O02" or "R3-O02.to.R3-S05";
    private (SceneGeometry Main,SceneGeometry Side,Port Out,Port Return) Geometry(BranchSnapshot s)
    {var geo=_chapter.CurrentGeometry(s);var main=geo["R3-S05"];var side=geo["R3-O02"];var outgoing=main.Ports.Single(x=>x.Id=="R3-S05.to.R3-O02");var back=side.Ports.Single(x=>x.Id==outgoing.TargetPort);Require(back.TargetScene==main.Id&&back.TargetPort==outgoing.Id&&outgoing.TargetScene==side.Id&&side.Danger.Length==0&&new NavigationGrid(main).CanStand(outgoing.Stand,true)&&new NavigationGrid(side).CanStand(back.Stand,true)&&new NavigationGrid(main).FindPath(outgoing.Stand,main.Ports.Single(x=>x.TargetScene=="R3-S04").Stand,true).Length>0&&new NavigationGrid(side).FindPath(back.Stand,side.Spots.Single(x=>x.Id==WritingTask.Spot).Stand,true).Length>0,"实际配对出口、观察点或独立安全返程不可达。");return(main,side,outgoing,back);}
    private static bool Current(BranchSnapshot s,IEnumerable<SideWellSourceRead> reads)=>reads.All(x=>BranchOperations.Entity(s,x.EntityId)?.Revision==x.Revision);
    private SideWellEntrySafety CurrentSafety(BranchSnapshot s)
    {var safety=Read<SideWellEntrySafety>(s,SafetyId)??throw new InvalidOperationException("请在侧井配对出口明确检查实际安全后登记。");var facts=MainSafety(s);var geo=Geometry(s);Require(safety.ContractVersion==ContractVersion&&safety.ContentVersion==Observation.Version&&safety.MainGeometrySha256==VoyageRules.Hash(geo.Main)&&safety.SideGeometrySha256==VoyageRules.Hash(geo.Side)&&safety.LadderReceipt==facts.Ladder.ReceiptId&&safety.RailReceipt==facts.Rail.ReceiptId&&safety.BasicReceipt==facts.Basic.ReceiptId&&safety.Scope=="marked_observation_only_no_sampling"&&Current(s,safety.Reads),"安全版本或实际返回条件变更，请在原出口重新核对。");return safety;}
    private static StoredReceipt Evidence<T>(BranchSnapshot s,string action,T value)=>s.Receipts.Where(x=>x.ActionType==action&&x.ResultJson==StrictJson.Serialize(value)).OrderByDescending(x=>x.Sequence).FirstOrDefault()??throw new InvalidOperationException("当前侧井来源未真实提交。");
    private SideWellVisit Visit(BranchSnapshot s)
    {var v=Read<SideWellVisit>(s,VisitId)??throw new InvalidOperationException("必须从已核验的真实配对出口进入侧井。");Require(v.Instance!=Guid.Empty&&v.FromPort=="R3-S05.to.R3-O02"&&v.ToPort=="R3-O02.to.R3-S05"&&v.Scene=="R3-O02"&&Actor(s).Scene=="R3-O02"&&Actor(s).ActionClock>=v.ArrivalClock&&s.Receipts.Any(r=>r.ActionType=="scene_transition"&&StrictJson.Deserialize<TraversedConnection>(r.ResultJson) is{From:"R3-S05",To:"R3-O02"} t&&t.ActionClock==v.ArrivalClock&&t.FromPort==v.FromPort&&t.ToPort==v.ToPort),"角色位置必须继承同一次实际配对到场，不能仅改场景名。");BranchOperations.Evidence(s,v.SafetyReceipt,"sidewell_entry_inspected");return v;}
    private void AtPort(BranchSnapshot s)
    {var a=Actor(s);var g=Geometry(s);var p=a.Scene==g.Main.Id?g.Out:a.Scene==g.Side.Id?g.Return:throw new InvalidOperationException("请到侧井实际配对入口。");Require(a.Position.Distance(p.Stand)<=2.5,"请先走到侧井对应出口站位。");if(a.Scene==g.Side.Id)Visit(s);}
    private void At(BranchSnapshot s,string spot)
    {Visit(s);var g=Geometry(s).Side;var a=Actor(s);Require(g.Spots.Any(x=>x.Id==spot&&a.Position.Distance(x.Stand)<=2.5)&&new NavigationGrid(g).CanStand(a.Position,true),"请先到侧井原有标记观察站位。");}
    private string[] Reads(BranchSnapshot s)=>s.Entities.Select(e=>e.Id).Concat(new[]{"actor",SafetyId,VisitId,MeaningId,ResultId,"material:"+Material,"material:"+MainMaterial,"final:preparation"}).Distinct().ToArray();
    private CommitPlanCommand Plan(BranchSnapshot s,string key,string action,object body,ImmutableArray<EntityChange> changes=default,DraftStamp? draft=null)
        =>BranchOperations.Plan(_repository,s,key,action,changes.IsDefault?[]:changes,Reads(s),body,items:[new("R3-local:safety_kit:1","R3-LOCAL-SAFETY-KIT","installed","R3:patrol_safety_kit","installed","R3:patrol_safety_kit",null)],draft:draft);
    private async ValueTask<CommandResult> Execute(CommitPlanCommand c)
    {var ses=_repository.Session;if(c.Context.Profile!=ses.Profile||c.Context.Branch!=ses.Branch||c.Context.Load!=ses.Load||c.Context.ReleaseId!=ses.ReleaseId)return new(CommitStatus.Rejected,null,[new("stale_load",SafetyId,"读取世代变更，请重开核对清单。")]);if(_repository is not IEventLeaseStore leases)throw new InvalidOperationException("侧井现场操作需要原子前景占用。");string owner="sidewell:"+c.Context.Command.Value;Require(await leases.TryLeasesAsync(c.Context.Load,owner,["input:foreground"]),"另一前景工作尚未交接。");try{return await _repository.ExecuteAsync(c);}finally{await leases.ReleaseLeasesAsync(c.Context.Load,owner);}}
    public async ValueTask<CommandResult> InspectEntryAsync()
    {var s=await _repository.SnapshotAsync();var facts=MainSafety(s);AtPort(s);var g=Geometry(s);var reads=new[]{"chapter3","R3:result:ENC-R3-01","material:R3-Q301-R-LADDER","material:R3-Q301-R-BASIC"}.Select(id=>new SideWellSourceRead(id,BranchOperations.Entity(s,id)?.Revision??throw new InvalidOperationException("当前安全原件未取得。"))).ToImmutableArray();var p=new SideWellEntrySafety(ContractVersion,Observation.Version,VoyageRules.Hash(g.Main),VoyageRules.Hash(g.Side),facts.Ladder.ReceiptId,facts.Rail.ReceiptId,facts.Basic.ReceiptId,reads,"marked_observation_only_no_sampling");return await Execute(Plan(s,"R3-O02:safety:"+Guid.NewGuid(),"sidewell_entry_inspected",p,[BranchOperations.Change(s,SafetyId,"sidewell_entry_safety",p)]));}
    public async ValueTask<CommandResult> RegisterEntrySafetyAsync()
    {
        var s=await _repository.SnapshotAsync();AtPort(s);var safety=CurrentSafety(s);Evidence(s,"sidewell_entry_inspected",safety);var c=_catalog.Connections.Single(x=>x.A=="R3-S05"&&x.B=="R3-O02"||x.A=="R3-O02"&&x.B=="R3-S05");var deps=safety.Reads.Select(x=>new EntityStamp(x.EntityId,x.Revision)).Append(new(SafetyId,BranchOperations.Entity(s,SafetyId)!.Revision)).ToImmutableArray();var proof=new ConnectionSafetyState(c.A,c.B,TravelService.Contract(c),true,true,deps,"");var committed=await Execute(Plan(s,"R3-O02:connection-proof:"+Guid.NewGuid(),"connection_safety_verified",proof));Require(committed.Status==CommitStatus.Committed&&committed.Receipt is not null,"本次实际连接安全未提交。");return await new TravelService(_repository,_catalog,_chapter.CurrentGeometry(await _repository.SnapshotAsync())).RegisterConnectionSafetyAsync(committed.Receipt!.Id.Value.ToString());
    }
    public string? PortIssue(BranchSnapshot s,Port p)
    {if(!OwnPort(p.Id))return "该出口不属于侧井观察范围。";try{CurrentSafety(s);var c=_catalog.Connections.Single(x=>x.A=="R3-S05"&&x.B=="R3-O02"||x.A=="R3-O02"&&x.B=="R3-S05");string id="travel-gate:"+TravelService.ConnectionKey(c.A,c.B);var gate=Read<ConnectionSafetyState>(s,id);Require(gate is not null&&gate.AllowAToB&&gate.AllowBToA&&gate.Contract==TravelService.Contract(c)&&gate.Dependencies.All(x=>BranchOperations.Entity(s,x.EntityId)?.Revision==x.Revision)&&gate.Dependencies.Any(x=>x.EntityId==SafetyId),"实际安全结果尚未登记到本条双向连接。");var original=StrictJson.Deserialize<ConnectionSafetyState>(BranchOperations.Evidence(s,gate!.AuthorityReceipt,"connection_safety_verified").ResultJson);Require(original.Dependencies.SequenceEqual(gate.Dependencies)&&original.AllowAToB&&original.AllowBToA,"登记来源不符。");return null;}catch(InvalidOperationException e){return e.Message;}}
    public async ValueTask<CommandResult> EnterPortAsync(string portId)
    {
        Require(OwnPort(portId),"不属于侧井配对连接。");var s=await _repository.SnapshotAsync();Safe(s);AtPort(s);var geo=Geometry(s);var a=Actor(s);var p=a.Scene==geo.Main.Id?geo.Out:geo.Return;Require(p.Id==portId&&PortIssue(s,p) is null,"当前双向入口安全、方向或注册结果未成立。");var target=a.Scene==geo.Main.Id?geo.Return:geo.Out;var next=a with{Scene=p.TargetScene,Position=target.Stand,ActionClock=checked(a.ActionClock+1)};var c=_catalog.Connections.Single(x=>x.A==p.TargetScene&&x.B==a.Scene||x.B==p.TargetScene&&x.A==a.Scene);string gate="travel-gate:"+TravelService.ConnectionKey(c.A,c.B);var safety=CurrentSafety(s);var proof=Evidence(s,"sidewell_entry_inspected",safety);var deps=safety.Reads.Select(x=>new EntityStamp(x.EntityId,x.Revision)).Append(new(SafetyId,BranchOperations.Entity(s,SafetyId)!.Revision)).Append(new(gate,BranchOperations.Entity(s,gate)!.Revision)).ToImmutableArray();var changes=ImmutableArray.CreateBuilder<EntityChange>();changes.Add(BranchOperations.Change(s,"actor","actor",next));if(next.Scene=="R3-O02")changes.Add(BranchOperations.Change(s,VisitId,"sidewell_actual_visit",new SideWellVisit(Guid.NewGuid(),p.Id,target.Id,next.Scene,next.ActionClock,proof.ReceiptId)));return await Execute(Plan(s,"R3-O02:port:"+Guid.NewGuid(),"scene_transition",new TraversedConnection(a.Scene,next.Scene,p.Id,target.Id,p.Stand,target.Stand,next.ActionClock,TravelService.Contract(c),deps,true),changes.ToImmutable()));
    }
    public async ValueTask<CommandResult> RecordWalkedRouteAsync(string receipt)=>await new TravelService(_repository,_catalog,_chapter.CurrentGeometry(await _repository.SnapshotAsync())).RecordWalkedRouteAsync(receipt);
    public async ValueTask<CommandResult> DiscoverObservationAsync(){var s=await _repository.SnapshotAsync();Safe(s);CurrentSafety(s);At(s,Observation.Spot);return await _chapter.DiscoverAsync(Material);}
    private static bool Acquired(BranchSnapshot s,ChapterMaterial m)=>Read<ChapterMaterialAccess>(s,"material:"+m.Id) is{} a&&a.Id==m.Id&&a.Version==m.Version&&a.TranslationVersion==m.TranslationVersion&&a.Fingerprint==m.Fingerprint&&a.SourceRoot==m.SourceRoot;
    public async ValueTask<ChapterMaterial> OpenObservationAsync(){var s=await _repository.SnapshotAsync();Require(Acquired(s,Observation),"侧井原记录尚未实际取得。");return Observation;}
    public async ValueTask<DraftSaved> SaveDraftAsync(long revision,DraftId? draft,string body){var ses=_repository.Session;return await _repository.SaveAsync(new(ses.Profile,ses.Branch,ses.Load,Task,draft,revision,body,Observation.Version));}
    public async ValueTask<CommandResult> ConfirmMeaningAsync(ImmutableDictionary<string,string> fields,bool assisted)
    {var s=await _repository.SnapshotAsync();Safe(s);CurrentSafety(s);At(s,WritingTask.Spot);Require(Acquired(s,Observation)&&Acquired(s,MainObservation),"两处原观察记录未实际取得。");var d=await _repository.GetDraftAsync(Task);Require(d is{Deleted:false}&&!string.IsNullOrWhiteSpace(d.Body),"比较便条须真实保存，结构化意思不能替代正文。");return await Execute(Plan(s,"R3-O02:meaning:"+Guid.NewGuid(),"sidewell_note_meaning_confirmed",new{structured_assistance=assisted,free_english_understanding="not_claimed",language_score=(string?)null},[BranchOperations.Change(s,MeaningId,"sidewell_note_meaning",new SideWellNoteMeaning(d!.Hash,assisted,fields))],new(Task,d.Id,d.Revision,d.Hash)));}
    public async ValueTask<SideWellPreview> PreviewComparisonAsync()
    {
        var s=await _repository.SnapshotAsync();Safe(s);CurrentSafety(s);At(s,WritingTask.Spot);var issues=ImmutableArray.CreateBuilder<RuleIssue>();void Check(bool ok,string code,string text){if(!ok)issues.Add(new(code,ResultId,text));}Check(!BranchOperations.Receipt(s,Completion),"already_registered","同一来源比较便条已登记，不发重复奖励。");Check(Acquired(s,Observation)&&Acquired(s,MainObservation),"source_missing","须实际取得侧井与主采点原记录。");var d=await _repository.GetDraftAsync(Task);var meaning=Read<SideWellNoteMeaning>(s,MeaningId);Check(d is{Deleted:false}&&!string.IsNullOrWhiteSpace(d.Body)&&meaning is not null&&meaning.DraftHash==d.Hash,"current_draft_missing","保存正文、稿件版本与逐项意思核对须一致。");bool F(string k,string v)=>meaning?.Fields.GetValueOrDefault(k)==v;Check(F("side","one_load_five_reading")&&F("main","one_load_four_reading")&&F("comparison","different_locations_conditions")&&F("unknown_conditions","unknown_not_copied")&&F("causality","not_proven")&&F("next_check","record_instrument_pump_stage")&&F("sampling","no_additional_assignment"),"bounded_comparison","保留两处读数和地点条件差异、未知条件与未来核验，不声称受控因果、追加采样或隐藏结局。");if(issues.Count>0)return new(Guid.Empty,false,issues.ToImmutable(),d?.Hash);var result=new SideWellComparisonResult(Visit(s).Instance,Observation.Fingerprint,MainObservation.Fingerprint,d!.Hash,meaning!.StructuredAssistance,"different_locations_conditions","unknown_not_copied","not_proven","no_additional_assignment",0,0,0);var plan=Plan(s,Completion,"sidewell_comparison_note_registered",result,[BranchOperations.Change(s,ResultId,"optional_comparison_note",result)],new(Task,d.Id,d.Revision,d.Hash));Guid token=Guid.NewGuid();_previews[token]=plan;return new(token,true,[],d.Hash);
    }
    public ValueTask<CommandResult> ConfirmPreviewAsync(Guid token)=>_previews.TryGetValue(token,out var c)?Execute(c):ValueTask.FromResult(new CommandResult(CommitStatus.Rejected,null,[new("preview_closed",ResultId,"侧井比较清单已关闭。") ]));
    public void ClosePreview(Guid token)=>_previews.Remove(token);
}
